function cl_hafrik_features_default_off(): array {return ['legacy_people_nearby','ai_characters','club_pappi','app_launches','app_travel','app_homes','app_cantaball','app_story','app_politics','app_delivery','app_needs','app_together','app_opportunities','app_journal','app_meet','app_firstday','app_events','uni_years','uni_food','wardrobe_locks','micro_style','real_sitting','gossip_room','gossip_show','gossip_wall','gossip_city','gossip_rep','hospital_care','hospital_checkup','hospital_pharmacy','hospital_staff'];}
function cl_hafrik_features(): array {
 $defaults=array_fill_keys(array_keys(cl_hafrik_feature_labels()),true);
 // Switches that start OFF. legacy_people_nearby: one-city Link Up replaced the old Nearby screen (Oct 2026); it is kept, not deleted.
 // ai_characters and club_pappi: switched off by the founder (Oct 2026) and replaced in the Club by the canned Hypeman; both kept, not deleted.
 // app_*: one-city phone apps hidden by the founder's slim phone (28 Oct 2026); switching one on shows it under More.
 // uni_years, uni_food, wardrobe_locks, micro_style, real_sitting: University Years plan (docs/UNIVERSITY-YEARS-PLAN.md), built behind these.
 // gossip_room, gossip_show, gossip_wall, gossip_city, gossip_rep: Gossip Room plan (docs/GOSSIP-ROOM-PLAN.md).
 // hospital_care, hospital_checkup, hospital_pharmacy, hospital_staff: Hospital plan (docs/HOSPITAL-PLAN.md).
 foreach(cl_hafrik_features_default_off() as $key)$defaults[$key]=false;
 $row=cl_one("SELECT value FROM chinalife_settings WHERE name='hafrik_features'");
 $saved=$row?json_decode($row['value'],true):null;
 if(is_array($saved))foreach($defaults as $key=>$value)if(isset($saved[$key])&&is_bool($saved[$key]))$defaults[$key]=$saved[$key];
 return $defaults;
}
function cl_hafrik_require(string $feature): void {
 if(!(cl_hafrik_features()[$feature]??false))cl_fail('This Hafrik feature is currently switched off in ChinaLife',403);
}
